from datetime import datetime, timedelta
from airflow.decorators import dag, task

@dag(schedule="@daily", start_date=datetime(2025, 1, 1), catchup=False,
     default_args={"retries": 2, "retry_delay": timedelta(minutes=5)})
def train_daily():
    @task
    def build_features(data_interval_start=None) -> str:
        # write to a partition keyed by the interval, overwrite on rerun
        return f"features/dt={data_interval_start:%Y-%m-%d}/"

    @task
    def train(path: str) -> str:
        print("training on", path)
        return "model-version-ref"

    train(build_features())

train_daily()

from metaflow import FlowSpec, step
class TrainFlow(FlowSpec):
    @step
    def start(self):
        self.alphas = [0.1, 1.0, 10.0]
        self.next(self.train, foreach="alphas")
    @step
    def train(self):
        self.alpha = self.input
        self.score = 1.0 / (1.0 + self.alpha)  # stand-in for a real fit
        self.next(self.join)
    @step
    def join(self, inputs):
        self.best = max(inputs, key=lambda i: i.score).alpha
        self.next(self.end)
    @step
    def end(self):
        print("best alpha", self.best)
if __name__ == "__main__":
    TrainFlow()

from fastapi import FastAPI, HTTPException
from pydantic import BaseModel

app = FastAPI()
model = None

class Req(BaseModel):
    features: list[float]

@app.get("/readyz")
def ready():
    if model is None:
        raise HTTPException(503, "model not loaded")
    return {"status": "ready"}

@app.post("/v1/models/churn:predict")
def predict(req: Req):
    score = model.predict([req.features])[0]
    return {"score": float(score), "model_version": "3"}

